import { NextFunction, Request, Response, Router } from 'express';
import { TaskManagementService } from '../application/task-management-service';
import { asTaskStatus } from '../domain/task-status';

type Body = Record<string, unknown>;

function text(body: Body, key: string, required = false): string | undefined {
  const value = body[key];
  if (value === undefined && !required) return undefined;
  if (typeof value !== 'string') throw new TypeError(`${key} must be a string`);
  return value;
}

function parameter(value: string | string[]): string {
  if (Array.isArray(value)) throw new TypeError('Route parameter must be a single value');
  return value;
}

export class TaskController {
  public constructor(private readonly service: TaskManagementService) {}

  public router(): Router {
    const router = Router();
    router.post('/users', this.handle((req) => this.service.createUser({ name: text(req.body as Body, 'name', true)! }), 201));
    router.post('/projects', this.handle((req) => this.service.createProject({ name: text(req.body as Body, 'name', true)! }), 201));
    router.post('/projects/:projectId/tasks', this.handle((req) => {
      const body = req.body as Body;
      const status = text(body, 'status');
      return this.service.createTask({ projectId: parameter(req.params.projectId), title: text(body, 'title', true)!,
        description: text(body, 'description'), dueDate: text(body, 'dueDate'), assigneeId: text(body, 'assigneeId'),
        status: status === undefined ? undefined : asTaskStatus(status) });
    }, 201));
    router.get('/projects/:projectId/tasks', this.handle((req) => {
      const status = typeof req.query.status === 'string' ? asTaskStatus(req.query.status) : undefined;
      const assigneeId = typeof req.query.assigneeId === 'string' ? req.query.assigneeId : undefined;
      return this.service.listProjectTasks(parameter(req.params.projectId), { status, assigneeId });
    }));
    router.patch('/tasks/:taskId/done', this.handle((req) => this.service.markTaskDone(parameter(req.params.taskId))));
    return router;
  }

  private handle(action: (request: Request) => unknown, status = 200) {
    return (request: Request, response: Response, next: NextFunction): void => {
      try { response.status(status).json(action(request)); } catch (error) { next(error); }
    };
  }
}

